MANUSCRIPT = ROOT / 'state/manuscript/Peg_Leg_Greg_Running_Manuscript.md'
STATE = ROOT / 'state/MANUSCRIPT_STATE.md'
OPEN = ROOT / 'state/OPEN_THREADS.md'
